int bpow(int a, int b)
{
    if(!b)
        return 1;
    int res = bpow(a, b >> 1);
    res = (res * 1ll * res) % MOD;
    if(b & 1)
        res = (res * 1ll * a) % MOD;
    return res;
}

void calcCP(int n, int s)
{
    if(!s)
        CP[n][s] = 1;
    else
    {
        CP[n][s] = (CP[n - 1][s - 1] * 1ll * bpow(pgreater, n - s)) % MOD + (CP[n - 1][s] * 1ll * bpow(pless, s)) % MOD;
        if(CP[n][s] >= MOD)
            CP[n][s] -= MOD;
    }
}

void calcStrong(int n)
{
    STRONG[n] = 1;
    if(n > 1)
    {
        for(int i = 1; i < n; ++i)
        {
            STRONG[n] -= (STRONG[i] * 1ll * CP[n][i]) % MOD;
            if(STRONG[n] < 0)
                STRONG[n] += MOD;
        }
    }
}

void calcAns(int n)
{
    if(n < 2)
        ans[n] = 0;
    else
    {
        for(int i = 1; i <= n; ++i)
        {
            ans[n] += STRONG[i] * 1ll * CP[n][i] % MOD * 1ll * (i * (n - i) + (i * (i - 1)) / 2 + (long long) (i < n ? ans[i] : 0) + ans[n - i]) % MOD;
            if(ans[n] >= MOD)
                ans[n] -= MOD;
        }
        int coef = 1 - (STRONG[n] * 1ll * CP[n][n]) % MOD;

        if(coef < 0)
            coef += MOD;

        ans[n] = (ans[n] * 1ll * bpow(coef, MOD - 2)) % MOD;
    }
}

main()
{
//    freopen("input.txt", "r", stdin);
    ios_base :: sync_with_stdio(false);
    cin.tie(NULL);

    int n, a, b;
    cin >> n >> a >> b;

    pless = (a * 1ll * bpow(b, MOD - 2)) % MOD;
    pgreater = ((b - a) * 1ll * bpow(b, MOD - 2)) % MOD;

    for(int i = 0; i <= n; ++i)
        for(int j = 0; j <= i; ++j)
            calcCP(i, j);

    for(int i = 0; i <= n; ++i)
        calcStrong(i);

    for(int i = 0; i <= n; ++i)
        calcAns(i);

    cout << ans[n] << '\n';

    return 0;
}
